pattern = r"\[global=(\d+)\]\s*Loss=([\d.]+)"
matches = re.findall(pattern, log_data)

steps = [int(m[0]) for m in matches]
losses = [float(m[1]) for m in matches]

plt.figure(figsize=(12, 6))
plt.plot(steps, losses, color='#1f77b4', linewidth=2, marker='o', markersize=4, alpha=0.8)
plt.title("AudioDiT Training Loss Over Global Steps", fontsize=16, fontweight='bold', pad=15)
plt.xlabel("Global Step", fontsize=12, fontweight='medium')
plt.ylabel("Loss", fontsize=12, fontweight='medium')
plt.grid(True, linestyle='--', alpha=0.6)
plt.tight_layout()

plt.savefig('/kaggle/working/AudioDiT_Loss_Plots.png', bbox_inches='tight', dpi=300)
plt.show()